// Innistrad (ISD) cards
pub mod isd;
pub use isd::*;

use std::collections::HashMap;

use crate::actions::Target;
use crate::ids::{CardId, ObjectId, PlayerId};
use crate::state::GameState;
use crate::types::*;

/// Static card data — the printed card.
#[derive(Debug, Clone)]
pub struct CardData {
    pub name: String,
    pub cost: Option<ManaCost>,
    pub card_types: Vec<CardType>,
    pub supertypes: Vec<Supertype>,
    pub subtypes: Vec<String>,
    pub power: Option<i32>,
    pub toughness: Option<i32>,
    pub oracle_text: String,
    pub keywords: Vec<Keyword>,
    pub flashback_cost: Option<ManaCost>,
    /// Declarative continuous effects this card has while on the battlefield.
    /// The engine reads these instead of parsing oracle_text.
    pub continuous_effects: Vec<ContinuousEffect>,
    /// Triggered abilities this card has. The engine uses these to know which
    /// events this card cares about and to display trigger descriptions on the stack.
    pub triggered_abilities: Vec<TriggeredAbilityDef>,
    /// Additional cost required to cast this spell (beyond mana).
    pub additional_cost: Option<AdditionalCost>,
}

/// A mana ability definition.
pub struct ManaAbilityDef {
    pub ability_index: usize,
    pub description: String,
    pub produced: Vec<(ManaType, u32)>,
    pub requires_tap: bool,
}

/// What sacrifice cost an activated ability requires.
#[derive(Debug, Clone, PartialEq)]
pub enum SacrificeCost {
    /// No sacrifice required.
    None,
    /// Sacrifice the permanent with this ability.
    SacrificeThis,
    /// Sacrifice any creature you control.
    SacrificeCreature,
    /// Sacrifice another creature you control (not the source permanent).
    SacrificeAnotherCreature,
}

/// An additional cost required to cast a spell (beyond mana).
#[derive(Debug, Clone)]
pub enum AdditionalCost {
    /// Sacrifice a creature you control (Altar's Reap, Infernal Plunge).
    SacrificeCreature,
    /// Exile N creature cards from your graveyard (Makeshift Mauler, Stitched Drake).
    ExileCreaturesFromGraveyard(usize),
    /// Exile X cards from your graveyard (Harvest Pyre), where X is chosen by
    /// the player at cast time. The engine generates one cast action per possible X.
    /// The count is stored on the spell object's card_state as "exile_count".
    ExileXFromGraveyard,
}

/// A non-mana activated ability definition.
pub struct ActivatedAbilityDef {
    pub ability_index: usize,
    pub description: String,
    pub cost: ManaCost,
    pub requires_tap: bool,
    /// Sacrifice cost required in addition to mana.
    pub sacrifice_cost: SacrificeCost,
    /// Target requirement for this ability (None = untargeted).
    pub target_requirement: Option<TargetRequirement>,
    /// Can only be activated once per turn.
    pub once_per_turn: bool,
    /// Can only be activated at sorcery speed.
    pub sorcery_speed_only: bool,
}

/// A loyalty ability on a planeswalker.
pub struct LoyaltyAbilityDef {
    pub ability_index: usize,
    /// Loyalty change: positive adds, negative removes, zero is free.
    pub loyalty_change: i32,
    pub description: String,
    /// Target requirement for this ability (None = untargeted).
    pub target_requirement: Option<TargetRequirement>,
}

/// What kind of event triggers an ability.
#[derive(Debug, Clone, PartialEq)]
pub enum TriggerKind {
    /// When this permanent enters the battlefield.
    EntersBattlefield,
    /// When this creature dies (battlefield → graveyard).
    SelfDies,
    /// Whenever another creature dies (death-watch).
    AnyCreatureDies,
    /// Whenever another creature enters the battlefield (ETB-watch).
    AnyCreatureEnters,
    /// When this creature deals combat damage to a player.
    CombatDamageToPlayer,
    /// Whenever any creature deals combat damage to a player (watches others).
    AnyCombatDamageToPlayer,
    /// Whenever any creature deals damage (combat or non-combat) to a player.
    AnyDamageToPlayer,
    /// At the beginning of each upkeep.
    Upkeep,
    /// At the beginning of each end step.
    EndStep,
    /// Whenever a player casts an instant or sorcery spell (spell-cast watcher).
    SpellCast,
    /// When this creature attacks.
    Attacks,
    /// When this creature blocks.
    Blocks,
    /// When this creature becomes blocked (attacked and something blocked it).
    BecomesBlocked,
    /// Whenever any creature attacks — watcher on other permanents (like AnyCreatureDies).
    AnyCreatureAttacks,
    /// When this creature deals combat damage to a creature.
    DealsCombatDamageToCreature,
    /// At the beginning of end of combat step.
    EndCombat,
    /// When this permanent leaves the battlefield.
    LeavesBattlefield,
}

/// A triggered ability definition on a card.
#[derive(Debug, Clone)]
pub struct TriggeredAbilityDef {
    /// What event triggers this ability.
    pub kind: TriggerKind,
    /// Human-readable description of what the trigger does (for stack/log display).
    pub description: String,
}

/// Typed filter for creature or permanent targeting restrictions.
/// Used instead of stringly-typed filters for compile-time safety.
#[derive(Debug, Clone, PartialEq)]
pub enum TargetFilter {
    /// No additional restriction beyond the base type.
    Any,
    /// Only creatures/permanents you control.
    YouControl,
    /// Only creatures/permanents you don't control.
    YouDontControl,
    /// Only nonblack creatures (Doom Blade).
    Nonblack,
    /// Only non-Vampire, non-Werewolf, non-Zombie (Victim of Night).
    NotSubtypes(Vec<String>),
    /// Only creatures with power >= N (Smite the Monstrous).
    PowerAtLeast(i32),
    /// Only attacking creatures (Rebuke).
    Attacking,
    /// Only noncreature permanents (Bramblecrush).
    Noncreature,
    /// Only permanents with specific card types (Naturalize: artifact or enchantment).
    HasCardType(Vec<CardType>),
    /// Only permanents with specific subtypes or card types (Urgent Exorcism: Spirit or enchantment).
    SubtypeOrCardType { subtypes: Vec<String>, card_types: Vec<CardType> },
    /// Only creatures with a specific subtype (Olivia Voldaren: target Vampire).
    HasSubtype(String),
    /// "Another" — excludes the source permanent from valid targets.
    Another,
    /// Only creatures with the same name as the source permanent (Evil Twin).
    SameNameAsSource,
}

impl std::fmt::Display for TargetFilter {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TargetFilter::Any => write!(f, "any"),
            TargetFilter::YouControl => write!(f, "you control"),
            TargetFilter::YouDontControl => write!(f, "you don't control"),
            TargetFilter::Nonblack => write!(f, "nonblack"),
            TargetFilter::NotSubtypes(types) => write!(f, "non-{}", types.join("/")),
            TargetFilter::PowerAtLeast(n) => write!(f, "power {}+", n),
            TargetFilter::Attacking => write!(f, "attacking"),
            TargetFilter::Noncreature => write!(f, "noncreature"),
            TargetFilter::HasCardType(types) => {
                let names: Vec<&str> = types.iter().map(|t| match t {
                    CardType::Artifact => "artifact",
                    CardType::Enchantment => "enchantment",
                    CardType::Creature => "creature",
                    CardType::Instant => "instant",
                    CardType::Sorcery => "sorcery",
                    CardType::Land => "land",
                    CardType::Planeswalker => "planeswalker",
                }).collect();
                write!(f, "{}", names.join(" or "))
            }
            TargetFilter::HasSubtype(subtype) => write!(f, "{}", subtype),
            TargetFilter::Another => write!(f, "another"),
            TargetFilter::SameNameAsSource => write!(f, "with the same name"),
            TargetFilter::SubtypeOrCardType { subtypes, card_types } => {
                let mut parts: Vec<String> = subtypes.clone();
                for t in card_types {
                    parts.push(match t {
                        CardType::Enchantment => "enchantment".into(),
                        CardType::Artifact => "artifact".into(),
                        _ => format!("{:?}", t).to_lowercase(),
                    });
                }
                write!(f, "{}", parts.join(" or "))
            }
        }
    }
}

/// Describes what targets a spell needs when cast.
#[derive(Debug, Clone)]
pub enum TargetRequirement {
    /// No targets needed (vanilla creatures, Divination, etc.)
    None,
    /// Target any creature or player ("any target" — Lightning Bolt)
    AnyTarget,
    /// Target a creature only (Giant Growth, Doom Blade)
    Creature,
    /// Target a creature matching a filter (Doom Blade: "nonblack creature")
    CreatureWithFilter(TargetFilter),
    /// Target a player only (Lava Axe)
    PlayerOnly,
    /// Target a player or planeswalker (Stensia Bloodhall)
    PlayerOrPlaneswalker,
    /// Target a spell on the stack (Counterspell)
    Spell,
    /// Target any permanent on the battlefield matching a filter (Naturalize, Bramblecrush)
    PermanentWithFilter(TargetFilter),
    /// Two separate targets (Prey Upon, Lost in the Mist). Engine generates Cartesian product.
    TwoTargets(Box<TargetRequirement>, Box<TargetRequirement>),
    /// Up to N targets matching the inner requirement (Travel Preparations).
    UpToTargets(usize, Box<TargetRequirement>),
    /// Target a card in any player's graveyard (Purify the Grave).
    GraveyardCard,
    /// Target a creature card in any graveyard (Ghoulcaller's Chant mode 1).
    GraveyardCreature,
    /// Target a creature card with a specific subtype in any graveyard (Ghoulcaller's Chant mode 2).
    GraveyardCreatureOfSubtype(String),
    /// Target a card in the caster's own graveyard (Memory's Journey mode 1).
    GraveyardCardOwnedByCaster,
    /// Target a card in an opponent's graveyard (Memory's Journey mode 2).
    GraveyardCardOwnedByOpponent,
    /// Target a card in exile (Runic Repetition).
    ExileCard,
    /// Choose one of several targeting modes (Ghoulcaller's Chant). Engine generates actions for each mode independently.
    ModalChoice(Vec<TargetRequirement>),
}

/// The trait that every card implements.
/// Provides static data and behavioral hooks.
pub trait CardBehavior: Send + Sync {
    fn card_data(&self) -> CardData;

    /// What targets does this spell require when cast?
    fn target_requirement(&self) -> TargetRequirement {
        TargetRequirement::None
    }

    /// Check if a specific target is valid for this spell.
    /// Called for each potential target when building legal actions.
    fn is_valid_target(&self, _state: &GameState, _caster: PlayerId, _target: &Target, _registry: &CardRegistry) -> bool {
        true
    }

    /// Whether this card can be cast from the graveyard (not flashback — stays in graveyard after).
    /// Used by Skaab Ruinator.
    fn can_cast_from_graveyard(&self) -> bool { false }

    /// Dynamic power/toughness for cards whose P/T depends on game state.
    /// Returns Some((power, toughness)) to override base P/T, or None for normal P/T.
    /// Called by effective_power/effective_toughness during P/T computation.
    /// Examples: Geist-Honored Monk (creatures you control), Wreath of Geists (creatures in graveyard).
    fn dynamic_pt(&self, _state: &GameState, _object_id: ObjectId) -> Option<(i32, i32)> {
        None
    }

    /// Called when this permanent enters the battlefield (ETB trigger).
    fn on_enter_battlefield(&self, _state: &mut GameState, _object_id: ObjectId, _registry: &CardRegistry) {}

    /// Called when this creature dies (moves from battlefield to graveyard).
    fn on_dies(&self, _state: &mut GameState, _object_id: ObjectId, _registry: &CardRegistry) {}

    /// Called when ANY creature dies. `self_id` is this permanent, `dead_id` is the deceased.
    /// `dead_damaged_by` and `dead_toughness` are last-known information captured before
    /// the zone change clears battlefield state.
    fn on_any_creature_dies(&self, _state: &mut GameState, _self_id: ObjectId, _dead_id: ObjectId, _dead_controller: PlayerId, _dead_damaged_by: &[ObjectId], _dead_toughness: i32, _registry: &CardRegistry) {}

    /// Called when ANY creature enters the battlefield. `self_id` is this permanent, `entered_id` is the new creature.
    /// Similar to on_any_creature_dies but for ETB. Used by Champion of the Parish.
    fn on_any_creature_enters(&self, _state: &mut GameState, _self_id: ObjectId, _entered_id: ObjectId, _entered_controller: PlayerId, _registry: &CardRegistry) {}

    /// Called when this creature deals combat damage to a player.
    /// Used by Stromkirk Noble, Falkenrath Marauders, Sturmgeist, etc.
    fn on_combat_damage_to_player(&self, _state: &mut GameState, _self_id: ObjectId, _damaged_player: PlayerId, _amount: u32, _registry: &CardRegistry) {}

    /// Called when this creature deals combat damage to another creature.
    /// Used by Creepy Doll.
    fn on_deals_combat_damage_to_creature(&self, _state: &mut GameState, _self_id: ObjectId, _damaged_creature: ObjectId, _amount: u32, _registry: &CardRegistry) {}

    /// Called when ANY creature deals combat damage to a player.
    /// `self_id` is this permanent (the watcher), `source_id` is the creature that dealt damage.
    /// Used by Rakish Heir (watches Vampires).
    fn on_any_combat_damage_to_player(&self, _state: &mut GameState, _self_id: ObjectId, _source_id: ObjectId, _damaged_player: PlayerId, _amount: u32, _registry: &CardRegistry) {}

    /// Called when ANY creature deals damage (combat or non-combat) to a player.
    /// Used by Curiosity (watches enchanted creature).
    fn on_any_damage_to_player(&self, _state: &mut GameState, _self_id: ObjectId, _source_id: ObjectId, _damaged_player: PlayerId, _amount: u32, _registry: &CardRegistry) {}

    /// Called at the beginning of the upkeep step for each permanent with an upkeep trigger.
    fn on_upkeep(&self, _state: &mut GameState, _self_id: ObjectId, _registry: &CardRegistry) {}

    /// Called at the beginning of the end step for each permanent with an end-step trigger.
    fn on_end_step(&self, _state: &mut GameState, _self_id: ObjectId, _registry: &CardRegistry) {}

    /// Called at the beginning of the end of combat step.
    fn on_end_combat(&self, _state: &mut GameState, _self_id: ObjectId, _registry: &CardRegistry) {}

    /// Called when a player casts an instant or sorcery spell.
    /// `caster` is the player who cast the spell, `spell_id` is the spell object.
    fn on_spell_cast(&self, _state: &mut GameState, _self_id: ObjectId, _caster: PlayerId, _spell_id: ObjectId, _registry: &CardRegistry) {}

    /// Loyalty abilities for planeswalkers.
    fn loyalty_abilities(&self, _state: &GameState, _object_id: ObjectId) -> Vec<LoyaltyAbilityDef> { vec![] }

    /// Called when a loyalty ability is activated.
    fn on_loyalty_ability(&self, _state: &mut GameState, _self_id: ObjectId, _ability_index: usize, _targets: &[Target], _registry: &CardRegistry) {}

    /// Starting loyalty for planeswalkers.
    fn starting_loyalty(&self) -> Option<u32> { None }

    /// Called when this creature attacks (declared as an attacker).
    fn on_attacks(&self, _state: &mut GameState, _self_id: ObjectId, _registry: &CardRegistry) {}

    /// Called when this creature blocks (declared as a blocker).
    fn on_blocks(&self, _state: &mut GameState, _self_id: ObjectId, _blocked_attacker: ObjectId, _registry: &CardRegistry) {}

    /// Called when this creature becomes blocked (it attacked and a creature blocked it).
    fn on_becomes_blocked(&self, _state: &mut GameState, _self_id: ObjectId, _blocker_id: ObjectId, _registry: &CardRegistry) {}

    /// Called when ANY creature attacks — watcher for permanents that care about attacks.
    /// `self_id` is this watcher permanent, `attacker_id` is the attacking creature.
    fn on_any_creature_attacks(&self, _state: &mut GameState, _self_id: ObjectId, _attacker_id: ObjectId, _attacker_controller: PlayerId, _registry: &CardRegistry) {}

    /// Called when the equipped creature blocks or is blocked by another creature.
    /// Used by equipment like Wooden Stake. `self_id` is the equipment,
    /// `equipped_creature` is the creature wearing this equipment,
    /// `other_creature` is the creature on the other side of the block.
    fn on_equipment_block_trigger(&self, _state: &mut GameState, _self_id: ObjectId, _equipped_creature: ObjectId, _other_creature: ObjectId, _registry: &CardRegistry) {}

    /// Return a modified mana cost for this spell, or None to use the normal cost.
    /// Used for cost reduction (e.g., Blasphemous Act costs {1} less per creature).
    fn modified_cost(&self, _state: &GameState, _registry: &CardRegistry) -> Option<ManaCost> { None }

    /// For double-faced cards: return the back face data if this card has one.
    fn back_face_data(&self) -> Option<CardData> { None }

    /// For DFCs: check if the transform condition is met (called during upkeep for werewolves).
    fn should_transform(&self, _state: &GameState, _object_id: ObjectId, _registry: &CardRegistry) -> bool { false }

    /// Called when a state-triggered ability (CR 603.8) for this permanent resolves.
    /// State-triggered abilities check a condition continuously and trigger when the
    /// condition is first true. They don't trigger again while already on the stack.
    fn on_state_trigger(&self, _state: &mut GameState, _object_id: ObjectId, _registry: &CardRegistry) {}

    /// Called when this permanent leaves the battlefield (moves to any other zone).
    fn on_leave_battlefield(&self, _state: &mut GameState, _object_id: ObjectId, _registry: &CardRegistry) {}

    /// List of mana abilities this permanent has while on the battlefield.
    fn mana_abilities(&self, _state: &GameState, _object_id: ObjectId) -> Vec<ManaAbilityDef> {
        vec![]
    }

    /// Whether this permanent grants its controller hexproof (e.g., Witchbane Orb).
    fn grants_player_hexproof(&self) -> bool { false }

    /// Called after a mana ability is activated. Used for mana abilities with side effects
    /// (e.g., Deranged Assistant mills a card when tapped for mana).
    fn on_activate_mana_ability(&self, _state: &mut GameState, _object_id: ObjectId, _ability_index: usize, _registry: &CardRegistry) {}

    /// List of non-mana activated abilities this permanent has.
    fn activated_abilities(&self, _state: &GameState, _object_id: ObjectId, _registry: &CardRegistry) -> Vec<ActivatedAbilityDef> {
        vec![]
    }

    /// Called when a non-mana activated ability is activated.
    /// `targets` contains targets chosen by the player (empty if untargeted).
    fn on_activate_ability(&self, _state: &mut GameState, _object_id: ObjectId, _ability_index: usize, _targets: &[Target], _registry: &CardRegistry) {}

    /// Called after the player chooses and discards a card via ChooseCardFromHand
    /// that was initiated by this permanent. Used by Civilized Scholar to check
    /// if the discarded card was a creature and trigger untap/transform.
    fn on_discard_choice(&self, _state: &mut GameState, _self_id: ObjectId, _discarded_id: ObjectId, _registry: &CardRegistry) {}

    /// Called after the player answers a YesNo resolution choice initiated by this permanent.
    /// `yes` is true if the player chose yes, false if they declined.
    fn on_yes_no_choice(&self, _state: &mut GameState, _self_id: ObjectId, _yes: bool, _registry: &CardRegistry) {}

    /// Called when this spell resolves from the stack.
    /// `targets` contains the targets chosen at cast time.
    /// For permanents: default moves to battlefield.
    /// For instants/sorceries: override to apply effect.
    fn on_resolve(&self, state: &mut GameState, object_id: ObjectId, targets: &[Target], _registry: &CardRegistry) {
        let _ = targets; // default ignores targets
        // Default for permanents: move to battlefield.
        let card_data = self.card_data();
        if card_data.card_types.iter().any(|t| t.is_permanent()) {
            state.move_object(object_id, Zone::Battlefield);
            // If this is a planeswalker, set starting loyalty counters.
            if let Some(loyalty) = self.starting_loyalty() {
                // For X-cost planeswalkers, the x_value is already set on the object.
                let x = state.get_object(object_id).and_then(|o| o.x_value).unwrap_or(0);
                let total = if card_data.cost.as_ref().map(|c| c.symbols.iter().any(|s| matches!(s, crate::types::ManaSymbol::X))).unwrap_or(false) {
                    x
                } else {
                    loyalty
                };
                state.add_counters(object_id, crate::types::CounterType::Loyalty, total);
            }
        }
    }
}

/// Registry mapping CardIds to their behavior implementations.
pub struct CardRegistry {
    cards: HashMap<CardId, Box<dyn CardBehavior>>,
    next_id: u32,
    name_to_id: HashMap<String, CardId>,
}

impl CardRegistry {
    pub fn new() -> Self {
        Self {
            cards: HashMap::new(),
            next_id: 1,
            name_to_id: HashMap::new(),
        }
    }

    /// Register a card and return its assigned CardId.
    pub fn register(&mut self, card: Box<dyn CardBehavior>) -> CardId {
        let id = CardId(self.next_id);
        self.next_id += 1;
        let name = card.card_data().name.clone();
        self.cards.insert(id, card);
        self.name_to_id.insert(name, id);
        id
    }

    /// Look up a card's behavior by ID.
    pub fn get(&self, id: CardId) -> Option<&dyn CardBehavior> {
        self.cards.get(&id).map(|b| b.as_ref())
    }

    /// Look up a card ID by name.
    pub fn get_id_by_name(&self, name: &str) -> Option<CardId> {
        self.name_to_id.get(name).copied()
    }

    /// Get card data by ID.
    pub fn card_data(&self, id: CardId) -> Option<CardData> {
        self.get(id).map(|b| b.card_data())
    }

