#[test]
fn avacynian_priest_has_correct_stats() {
    let reg = registry();
    let id = reg.get_id_by_name("Avacynian Priest").unwrap();
    let data = reg.card_data(id).unwrap();
    assert_eq!(data.power, Some(1));
